#include "gadgets/web/Web.hpp"
#include <stdexcept>
namespace batbox::gadgets::web {
Json webSearchInputSchema(){return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"query":{"description":"The search query to use","type":"string","minLength":2},"allowed_domains":{"description":"Only include search results from these domains","type":"array","items":{"type":"string"}},"blocked_domains":{"description":"Never include search results from these domains","type":"array","items":{"type":"string"}}},"required":["query"],"additionalProperties":false})BATBOXSCHEMA");}
Json webSearchOutputSchema(){return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"query":{"description":"The search query that was executed","type":"string"},"results":{"description":"Search results and/or text commentary from the model","type":"array","items":{"anyOf":[{"type":"object","properties":{"tool_use_id":{"description":"ID of the tool use","type":"string"},"content":{"description":"Array of search hits","type":"array","items":{"type":"object","properties":{"title":{"description":"The title of the search result","type":"string"},"url":{"description":"The URL of the search result","type":"string"}},"required":["title","url"],"additionalProperties":false}}},"required":["tool_use_id","content"],"additionalProperties":false},{"type":"string"}]}},"durationSeconds":{"description":"Time taken to complete the search operation","type":"number"}},"required":["query","results","durationSeconds"],"additionalProperties":false})BATBOXSCHEMA");}
Json webFetchInputSchema(){return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"url":{"description":"The URL to fetch content from","type":"string","format":"uri"},"prompt":{"description":"The prompt to run on the fetched content","type":"string"}},"required":["url","prompt"],"additionalProperties":false})BATBOXSCHEMA");}
Json webFetchOutputSchema(){return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"bytes":{"description":"Size of the fetched content in bytes","type":"number"},"code":{"description":"HTTP response code","type":"number"},"codeText":{"description":"HTTP response code text","type":"string"},"result":{"description":"Processed result from applying the prompt to the content","type":"string"},"durationMs":{"description":"Time taken to fetch and process the content","type":"number"},"url":{"description":"The URL that was fetched","type":"string"}},"required":["bytes","code","codeText","result","durationMs","url"],"additionalProperties":false})BATBOXSCHEMA");}
} // namespace batbox::gadgets::web
